package com.shopsphere.security;import io.jsonwebtoken.Jwts;import io.jsonwebtoken.security.Keys;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import javax.crypto.SecretKey;import java.nio.charset.StandardCharsets;import java.util.Date;@Service public class JwtService{private final SecretKey key;private final long exp;public JwtService(@Value("${app.jwt.secret}")String s,@Value("${app.jwt.expiration-ms}")long e){key=Keys.hmacShaKeyFor(s.getBytes(StandardCharsets.UTF_8));exp=e;}public String generate(String email,String role){long n=System.currentTimeMillis();return Jwts.builder().subject(email).claim("role",role).issuedAt(new Date(n)).expiration(new Date(n+exp)).signWith(key).compact();}public String email(String t){return Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload().getSubject();}public boolean valid(String t){try{return Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload().getExpiration().after(new Date());}catch(Exception e){return false;}}}